import{_ as a,o as t,c as n,aa as o}from"./chunks/framework.BAs_AphD.js";const i="/buildary-help-preview/media/cs/tickets/m_hlavni_menu.png",s="/buildary-help-preview/media/cs/tickets/m_ikona_ukoly.png",l="/buildary-help-preview/media/cs/tickets/m_ikona_denik.png",r="/buildary-help-preview/media/cs/tickets/m_seznam_staveb.png",d="/buildary-help-preview/media/cs/tickets/m_detail_stavby.png",v="/buildary-help-preview/media/cs/tickets/m_nastaveni.png",y=JSON.parse('{"title":"Seznam staveb a menu v mobilu","description":"","frontmatter":{"title":"Seznam staveb a menu v mobilu","wiki":"cs:diary:m_project_list"},"headers":[],"relativePath":"diary/m_project_list.md","filePath":"diary/m_project_list.md","lastUpdated":1794209661000}'),k={name:"diary/m_project_list.md"};function m(p,e,u,b,c,h){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="seznam-staveb-a-menu-v-mobilu" tabindex="-1">Seznam staveb a menu v mobilu <a class="header-anchor" href="#seznam-staveb-a-menu-v-mobilu" aria-label="Permalink to &quot;Seznam staveb a menu v mobilu&quot;">​</a></h1><p>Menu mobilní aplikace vás dostane na jinou stavbu, do jiného deníku, do úkolů a do nastavení aplikace. V <strong>Seznamu staveb</strong> vyberete stavbu a rovnou otevřete její deník nebo úkoly.</p><p>Krok za krokem: <a href="/buildary-help-preview/akademie/mobilni-aplikace-denik">Psát deník v mobilu</a> v Akademii.</p><h2 id="menu-aplikace" tabindex="-1">Menu aplikace <a class="header-anchor" href="#menu-aplikace" aria-label="Permalink to &quot;Menu aplikace&quot;">​</a></h2><p>Menu otevřete ikonou tří vodorovných čar vlevo nahoře. Pokud je na jejím místě šipka zpět, klepněte nejdřív na ni – ikona menu se objeví o úroveň výš.</p><figure class="shot" style="--w:260px;"><img src="'+i+'" alt="Otevřené menu mobilní aplikace s odkazy na Seznam staveb, Nastavení, deník a úkoly" loading="lazy"></figure><p>V horní části menu vidíte název stavby, ve které právě jste, název naposledy otevřeného deníku a e-mail, kterým jste přihlášeni. Pod nimi jsou:</p><table tabindex="0"><thead><tr><th>Položka</th><th>K čemu slouží</th></tr></thead><tbody><tr><td><strong>Seznam staveb</strong></td><td>Přejít na jinou stavbu – viz níže.</td></tr><tr><td><strong>Nastavení</strong></td><td>Nastavení podpisu, offline režim, odhlášení – viz níže.</td></tr><tr><td><strong>Stavební deník</strong> → <strong>Seznam deníků</strong></td><td>Deníky aktuální stavby; odtud přejdete do jiného deníku.</td></tr><tr><td><strong>Stavební deník</strong> → <strong>Dokumenty deníku</strong></td><td>Dokumenty aktuálního deníku.</td></tr><tr><td><strong>Stavební deník</strong> → <strong>Denní záznamy</strong></td><td>Denní záznamy aktuálního deníku – viz <a href="/buildary-help-preview/diary/m_dailyentries">Denní záznamy v mobilu</a>.</td></tr><tr><td><strong>Management úkolů</strong> → <strong>Seznam úkolů</strong></td><td>Úkoly aktuální stavby – viz <a href="/buildary-help-preview/tickets/m_task_grid">Úkoly v mobilu</a>.</td></tr><tr><td><strong>Management úkolů</strong> → <strong>Výkresy a mapa</strong></td><td>Úkoly aktuální stavby jako značky na výkresech a v mapě – viz <a href="/buildary-help-preview/tickets/m_task_grid">Úkoly v mobilu</a>.</td></tr></tbody></table><p>Seznam deníků a Seznam úkolů se vždy týkají stavby uvedené nahoře v menu. Pokud chcete deník nebo úkoly jiné stavby, přejděte na ni nejdřív přes <strong>Seznam staveb</strong>.</p><p>Dole v menu je číslo verze aplikace.</p><h2 id="prejit-mezi-denikem-a-ukoly" tabindex="-1">Přejít mezi deníkem a úkoly <a class="header-anchor" href="#prejit-mezi-denikem-a-ukoly" aria-label="Permalink to &quot;Přejít mezi deníkem a úkoly&quot;">​</a></h2><p>Mezi deníkem a úkoly téže stavby přejdete jedním klepnutím na ikonu vpravo v záhlaví: v deníku na ikonu úkolů, v úkolech na ikonu deníku.</p><div class="shots"><figure class="shot" style="--w:260px;"><img src="'+s+'" alt="Ikona úkolů v záhlaví Stavebního deníku" loading="lazy"><figcaption>Z deníku do úkolů</figcaption></figure><figure class="shot" style="--w:260px;"><img src="'+l+'" alt="Ikona deníku v záhlaví Úkolů" loading="lazy"><figcaption>Z úkolů do deníku</figcaption></figure></div><h2 id="seznam-staveb" tabindex="-1">Seznam staveb <a class="header-anchor" href="#seznam-staveb" aria-label="Permalink to &quot;Seznam staveb&quot;">​</a></h2><p>V menu klepněte na <strong>Seznam staveb</strong>. Otevře se obrazovka <strong>Vybrat stavbu</strong> se všemi stavbami, do kterých máte přístup. Stavbu najdete i hledáním (lupa vpravo nahoře).</p><p>U každé stavby jsou tři tlačítka:</p><ul><li><strong>Detail</strong> (ikona s písmenem i) – rozbalí základní údaje o stavbě: název, stavebníka, zhotovitele, doménu a datum zahájení a ukončení.</li><li><strong>Deník</strong> – otevře stavební deník stavby. Pokud má stavba víc deníků, otevře jejich seznam.</li><li><strong>Úkoly</strong> – otevře Seznam úkolů stavby.</li></ul><p>Modul, který na stavbě není zapnutý, má tlačítko zašedlé.</p><div class="shots"><figure class="shot" style="--w:260px;"><img src="'+r+'" alt="Obrazovka Vybrat stavbu se seznamem staveb a tlačítky Detail, Deník a Úkoly" loading="lazy"></figure><figure class="shot" style="--w:260px;"><img src="'+d+'" alt="Rozbalený detail stavby se stavebníkem, zhotovitelem, doménou a datem zahájení" loading="lazy"></figure></div><p>Můžete klepnout i přímo na obrázek nebo název stavby:</p><ul><li>stavba s jedním deníkem se otevře na denních záznamech dnešního dne,</li><li>stavba s více deníky se otevře na seznamu deníků,</li><li>stavba, která má zapnutý jen Management úkolů, se otevře na Seznamu úkolů.</li></ul><p>Stavby se zakládají a nastavují jen na webu – viz <a href="/buildary-help-preview/diary/projectsetup">Založit stavbu</a>.</p><h2 id="nastaveni" tabindex="-1">Nastavení <a class="header-anchor" href="#nastaveni" aria-label="Permalink to &quot;Nastavení&quot;">​</a></h2><p>V menu klepněte na <strong>Nastavení</strong>. Najdete tu:</p><ul><li><strong>Nastavení podpisu</strong> – čím podepisujete; nastavení je společné s webem, viz <a href="/buildary-help-preview/diary/m_signing">Podepisování v mobilu</a>. Podpis potřebujete jen pro deník, úkoly se nepodepisují.</li><li><strong>Pracovat offline</strong> – přepne aplikaci do offline režimu, viz <a href="/buildary-help-preview/diary/m_offline">Práce bez signálu</a>.</li><li><strong>Zpětná vazba</strong> – formulář pro vaše připomínky a nápady k aplikaci.</li><li><strong>Novinky v aplikaci</strong> – okno s novinkami, které se ukazuje po přihlášení. Touto volbou ho kdykoli otevřete znovu.</li><li><strong>Odhlásit</strong> – odhlásí vás z aplikace, třeba když se chcete přihlásit jiným účtem.</li></ul><figure class="shot" style="--w:260px;"><img src="'+v+'" alt="Obrazovka Nastavení s volbami Nastavení podpisu, Pracovat offline, Zpětná vazba, Novinky v aplikaci a Odhlásit" loading="lazy"></figure>',26)])])}const z=a(k,[["render",m]]);export{y as __pageData,z as default};
